from matplotlib.patches import Rectangle
fig = plt.gcf(); fig.set_size_inches(6.6, 3.2)
ax = fig.add_axes([0, 0, 1, 1])
def rod(x, y, fc='white', hatch=None):
    for k in range(10):
        ax.add_patch(Rectangle((x, y + k * 0.3), 0.3, 0.3, fc=fc, ec='black', lw=0.8, hatch=hatch))
def one(x, y, fc='white', hatch=None):
    ax.add_patch(Rectangle((x, y), 0.3, 0.3, fc=fc, ec='black', lw=0.8, hatch=hatch))
