from matplotlib.patches import Rectangle
fig = plt.gcf(); fig.set_size_inches(6.6, 3.0)
ax = fig.add_axes([0, 0, 1, 1])
def rod(x, y, crossed=False):
    for k in range(10):
        ax.add_patch(Rectangle((x, y + k * 0.3), 0.3, 0.3, fill=False, ec='black', lw=0.8))
    if crossed:
        ax.plot([x - 0.1, x + 0.4], [y - 0.05, y + 3.05], color='red', lw=2)
def one(x, y, crossed=False, new=False):
    ax.add_patch(Rectangle((x, y), 0.3, 0.3, fc=(0.75, 0.85, 1.0) if new else 'white', ec='black', lw=0.8, hatch='////' if new else None))
    if crossed:
        ax.plot([x + 0.04, x + 0.26], [y + 0.04, y + 0.26], color='red', lw=1.6)
        ax.plot([x + 0.04, x + 0.26], [y + 0.26, y + 0.04], color='red', lw=1.6)
# left: 43 = 4 tens 3 ones
for i in range(4): rod(0.2 + i * 0.45, 0.6)
for j in range(3): one(2.2, 0.6 + j * 0.4)
ax.text(1.2, 0.15, '43: 4 tens, 3 ones', ha='center', va='center', fontsize=11)
ax.annotate('', xy=(3.6, 2.1), xytext=(2.8, 2.1), arrowprops=dict(arrowstyle='->', lw=1.5))
# right: 3 tens, 13 ones; cross 2 tens and 6 ones
for i in range(3): rod(4.0 + i * 0.45, 0.6, crossed=(i >= 1))
for j in range(13):
    c, r = divmod(j, 5)
    one(5.6 + c * 0.4, 0.6 + r * 0.4, crossed=(j >= 7), new=(j >= 3))
ax.text(5.6, 0.15, '3 tens, 13 ones', ha='center', va='center', fontsize=11)
ax.text(8.3, 2.3, 'take away', ha='center', va='center', fontsize=11, color='red')
ax.text(8.3, 1.9, '2 tens, 6 ones', ha='center', va='center', fontsize=11, color='red')
ax.text(8.3, 1.2, 'left: 1 ten,', ha='center', va='center', fontsize=11)
ax.text(8.3, 0.8, '7 ones = 17', ha='center', va='center', fontsize=11)
ax.set_xlim(0, 9.6); ax.set_ylim(-0.2, 3.8); ax.set_aspect('equal'); ax.axis('off')
